<?php
require_once dirname(__DIR__,3).'/bootstrap.php';$allowedRoles=[ROLE_ADMIN];require APP_ROOT.'/app/middleware/RoleMiddleware.php';use App\Services\FirebaseService;
$id=sanitize($_GET['id']??'');$notification=FirebaseService::getInstance()->getDocument(COL_NOTIFICATIONS,$id);if(!$notification){flash('error','Notification not found.');redirect(url('views/admin/notifications/index.php'));}if($_SERVER['REQUEST_METHOD']==='POST'){FirebaseService::getInstance()->updateDocument(COL_NOTIFICATIONS,$id,['read'=>true]);flash('success','Notification marked read.');redirect(url('views/admin/notifications/view.php?id='.urlencode($id)));}$pageTitle='Notification Details';$navItems=[['icon'=>'bi-bell','label'=>'Notifications','href'=>url('views/admin/notifications/index.php'),'active'=>true]];require APP_ROOT.'/app/views/components/header.php';require APP_ROOT.'/app/views/components/sidebar.php';?>
<div class="main-content"><?php require APP_ROOT.'/app/views/components/navbar.php';?><div class="content-wrapper"><div class="card stat-card p-4" style="max-width:760px"><div class="d-flex justify-content-between"><div><span class="badge bg-info mb-2"><?=e($notification['type']??'info')?></span><h5><?=e($notification['title']??'Notification')?></h5></div><a class="btn btn-outline-secondary btn-sm" href="<?=url('views/admin/notifications/index.php')?>">Back</a></div><hr><p><?=nl2br(e($notification['message']??''))?></p><div class="d-flex justify-content-between"><span class="badge <?=!empty($notification['read'])?'bg-success':'bg-warning text-dark'?>"><?=!empty($notification['read'])?'Read':'Unread'?></span><?php if(empty($notification['read'])):?><form method="POST"><button class="btn btn-primary btn-sm">Mark as read</button></form><?php endif;?></div></div></div></div><?php require APP_ROOT.'/app/views/components/footer.php';?>